// lib/widgets/escudo_vector.dart
// Escudo de la UPEA (Ingeniería de Sistemas) vectorizado a partir de assets/images/escudo.png.
// ARCHIVO GENERADO: no editar a mano. Cada contorno es una lista plana [x1, y1, x2, y2, ...]
// en el espacio ancho x alto. Se rellenan con PathFillType.evenOdd (los huecos quedan abiertos).
// Sirve para la animación de "el logo se dibuja" del splash (trazo del contorno y luego relleno).

import 'dart:ui';

class EscudoVector {
  EscudoVector._();

  /// Dimensiones del dibujo (relación de aspecto = ancho / alto).
  static const double ancho = 557.8;
  static const double alto = 559.8;

  /// Parte azul del escudo (escudo, aro de letras, engrane, libro). En el splash se dibuja clara.
  static final Path azul = _construir(_azul);

  /// Parte roja del escudo (cabeza con circuito). En el splash es el color de acento.
  static final Path rojo = _construir(_rojo);

  static Path _construir(List<List<double>> contornos) {
    final path = Path()..fillType = PathFillType.evenOdd;
    for (final c in contornos) {
      path.moveTo(c[0], c[1]);
      for (var i = 2; i < c.length; i += 2) {
        path.lineTo(c[i], c[i + 1]);
      }
      path.close();
    }
    return path;
  }

